import type { Question } from '../../lib/types'

export const network_cost_questions: Question[] = [
  { id: 'd4-net-001', domain: 4, topics: ['data transfer', 'egress', 'pricing'], type: 'single', stem: 'An EC2 instance in us-east-1 transfers 10 TB of data to the internet. What is the approximate cost?', options: [{ id: 'A', text: 'Free' }, { id: 'B', text: 'Approximately $920: first 100 GB free, next 10 TB at ~$0.09/GB; egress to internet is the most expensive data transfer type' }, { id: 'C', text: '$0.02/GB' }, { id: 'D', text: '$10 flat fee for any egress' }], correct: ['B'], explanation: 'EC2 internet egress pricing (us-east-1): First 100 GB/month free, next 9.9 TB at $0.09/GB ≈ $891. Data transfer to the internet is the most expensive type. 10 TB ≈ $900. Design architectures to minimize internet egress (use CloudFront, S3 Transfer Acceleration, or process data within AWS).', distractors: { A: 'Internet egress is charged — only intra-AZ same-account transfers are typically free.', C: '$0.02/GB is cross-region pricing — internet egress is higher at ~$0.09/GB.', D: 'Data transfer is metered per GB — no flat fee.' } },
  { id: 'd4-net-002', domain: 4, topics: ['data transfer', 'intra-AZ', 'free'], type: 'single', stem: 'Two EC2 instances communicate in the same AZ using private IPs. What is the data transfer cost?', options: [{ id: 'A', text: '$0.01/GB each way' }, { id: 'B', text: 'Free' }, { id: 'C', text: '$0.02/GB outbound only' }, { id: 'D', text: 'Same as internet egress' }], correct: ['B'], explanation: 'Intra-AZ data transfer between EC2 instances using private IP addresses is free. This is a key architectural principle: locate tightly coupled services in the same AZ to avoid data transfer costs. Inter-AZ transfer using private IPs is $0.01/GB each way.', distractors: { A: '$0.01/GB applies to inter-AZ transfers — same AZ private IP is free.', C: 'Same AZ private IP transfers are bidirectionally free.', D: 'Internet egress rates don\'t apply to intra-AZ private IP traffic.' } },
  { id: 'd4-net-003', domain: 4, topics: ['NAT Gateway', 'cost'], type: 'single', stem: 'Private subnet instances use a NAT Gateway to access the internet. Monthly bills show NAT Gateway data processing charges are unexpectedly high. What architectural change eliminates NAT Gateway charges for AWS service access?', options: [{ id: 'A', text: 'Move instances to public subnets' }, { id: 'B', text: 'Add VPC Endpoints (Gateway for S3/DynamoDB, Interface for other services)' }, { id: 'C', text: 'Use a NAT Instance instead' }, { id: 'D', text: 'Enable NAT Gateway HA' }], correct: ['B'], explanation: 'NAT Gateway charges: $0.045/hour + $0.045/GB processed. S3 and DynamoDB Gateway Endpoints are free and route traffic directly within the VPC. Interface Endpoints for other services ($0.01/hour + $0.01/GB) are often cheaper than NAT Gateway processing for high-volume AWS API traffic.', distractors: { A: 'Public subnets expose instances directly — introduces security risk.', C: 'NAT Instances still process data and incur instance + data transfer costs.', D: 'HA doesn\'t reduce NAT Gateway processing charges.' } },
  { id: 'd4-net-004', domain: 4, topics: ['CloudFront', 'cost', 'vs S3 direct'], type: 'single', stem: 'A company serves static content directly from S3 ($0.09/GB internet egress). Adding CloudFront would cost $0.01-0.085/GB to end users. For global high-traffic content, is CloudFront more expensive?', options: [{ id: 'A', text: 'CloudFront always costs more than S3 direct' }, { id: 'B', text: 'CloudFront is typically cheaper: S3-to-CloudFront egress is free; CloudFront delivers to users at lower rates than S3 internet egress; plus cache hits eliminate origin requests' }, { id: 'C', text: 'The costs are identical' }, { id: 'D', text: 'CloudFront is only cheaper in the US' }], correct: ['B'], explanation: 'CloudFront cost advantage: (1) S3-to-CloudFront transfer is free ($0 vs $0.09/GB from S3 directly), (2) CloudFront-to-user pricing is lower than S3 direct egress in most regions, (3) High cache hit ratios reduce S3 origin requests. For popular static content, CloudFront significantly reduces total delivery cost.', distractors: { A: 'For high-traffic global content, CloudFront is typically cheaper than S3 direct delivery.', C: 'The cost structure is different — CloudFront is generally cheaper for high-traffic workloads.', D: 'CloudFront price classes and cache benefits apply globally.' } },
  { id: 'd4-net-005', domain: 4, topics: ['Direct Connect', 'cost comparison', 'VPN'], type: 'single', stem: 'A company currently uses Site-to-Site VPN ($0.05/hour per tunnel). They transfer 1 PB/month. Direct Connect (10 Gbps dedicated) costs $1,620/month port charge + $0.02/GB data transfer. VPN data transfer is charged at internet egress rates ($0.09/GB). Which is cheaper at 1 PB/month?', options: [{ id: 'A', text: 'VPN' }, { id: 'B', text: 'Direct Connect' }, { id: 'C', text: 'They cost the same' }, { id: 'D', text: 'VPN is always cheaper than Direct Connect' }], correct: ['B'], explanation: 'Direct Connect data transfer is $0.02/GB vs VPN data egress at internet rates ($0.09/GB). At 1 PB (1,024 TB): Direct Connect = ~$20,480 + $1,620/month port; VPN = ~$92,160. At scale, Direct Connect data transfer savings far exceed the port charge. Break-even is typically around 100-200 TB/month.', distractors: { A: 'VPN is cheaper at low data volumes — Direct Connect becomes economical at higher volumes.', C: 'Pricing is very different — Direct Connect is significantly cheaper at 1 PB/month.', D: 'VPN is cheaper at low volumes but expensive per GB at scale.' } },
  { id: 'd4-net-006', domain: 4, topics: ['Transit Gateway', 'cost', 'peering'], type: 'single', stem: 'A company has 20 VPCs all connected through Transit Gateway. They pay $0.05/GB for TGW data processing. Some VPCs exchange large amounts of data (1 TB/day). What reduces TGW data processing costs for VPC-to-VPC traffic?', options: [{ id: 'A', text: 'Increase TGW bandwidth' }, { id: 'B', text: 'Create direct VPC peering between high-traffic VPC pairs' }, { id: 'C', text: 'Use Transit Gateway Connect instead' }, { id: 'D', text: 'Move all traffic to internet and back' }], correct: ['B'], explanation: 'For high-bandwidth VPC pairs, direct VPC peering eliminates TGW data processing charges ($0.05/GB). Same-region VPC peering intra-AZ is free; inter-AZ is $0.01/GB each way. If two VPCs exchange 1 TB/day, peering saves $0.05/GB × 1 TB ≈ $51/day vs TGW.', distractors: { A: 'TGW bandwidth is not a user-configurable setting.', C: 'TGW Connect is for SD-WAN/appliance connectivity — not a cost reduction for VPC-to-VPC traffic.', D: 'Internet routing adds latency and egress charges — not a cost optimization.' } },
  { id: 'd4-net-007', domain: 4, topics: ['NAT Gateway', 'per-AZ', 'optimization'], type: 'single', stem: 'A company has 3 AZs with private subnets. Currently all private instances route through a single NAT Gateway in AZ-1. EC2 instances in AZ-2 and AZ-3 pay $0.01/GB inter-AZ transfer to reach NAT GW in AZ-1. What reduces this cost?', options: [{ id: 'A', text: 'Use a single NAT Gateway for simplicity' }, { id: 'B', text: 'Deploy one NAT Gateway per AZ' }, { id: 'C', text: 'Use NAT Instances (no HA but cheaper)' }, { id: 'D', text: 'Route through VPC peering' }], correct: ['B'], explanation: 'One NAT GW per AZ is an AWS best practice for both HA and cost. Routing from AZ-2/3 to a NAT GW in AZ-1 incurs $0.01/GB inter-AZ charge PLUS $0.045/GB NAT processing. Per-AZ NAT GWs eliminate the inter-AZ charge for most internet-bound traffic.', distractors: { A: 'Single NAT GW creates both a single point of failure and unnecessary inter-AZ data transfer costs.', C: 'NAT Instances are cheaper per instance-hour but require management and lack auto-scaling.', D: 'VPC peering is for VPC-to-VPC — not for internet egress.' } },
  { id: 'd4-net-008', domain: 4, topics: ['VPC Interface Endpoints', 'cost', 'vs NAT'], type: 'single', stem: 'Private EC2 instances call AWS APIs (Secrets Manager, SSM, STS) through NAT Gateway. Monthly NAT processing for these calls is $200. VPC Interface Endpoints for these services cost $0.01/hour + $0.01/GB. Is the switch cost-effective?', options: [{ id: 'A', text: 'Always use NAT Gateway for all traffic' }, { id: 'B', text: 'Compare: 3 Interface Endpoints × $0.01/hour × 730 hours = $21.90/month + data; NAT Gateway at $200/month data processing; likely Interface Endpoints are cheaper' }, { id: 'C', text: 'Interface Endpoints are always more expensive' }, { id: 'D', text: 'Interface Endpoints have unlimited data charges' }], correct: ['B'], explanation: 'Interface Endpoint hourly cost: ~$7.30/endpoint/month. For 3 endpoints = $21.90/month + $0.01/GB data. If NAT is processing $200/month of AWS API traffic, Interface Endpoints are likely cheaper AND more secure (traffic stays in VPC). Always compare: endpoint hours + data vs. NAT processing charges.', distractors: { A: 'NAT Gateway is appropriate for internet access — not optimal for AWS service calls when endpoints exist.', C: 'For high-volume AWS API traffic, Interface Endpoints are often cheaper than NAT processing.', D: 'Interface Endpoints charge $0.01/GB — not unlimited/flat.' } },
  { id: 'd4-net-009', domain: 4, topics: ['data transfer', 'cross-region', 'same-AZ'], type: 'single', stem: 'A microservices architecture has services distributed across 3 AZs. Service A in AZ-1 frequently calls Service B. For cost optimization, should all services be in the same AZ?', options: [{ id: 'A', text: 'Yes' }, { id: 'B', text: 'It depends: same AZ = free transfers but single AZ = no fault tolerance; distribute across AZs for HA and accept $0.01/GB inter-AZ cost (often minimal vs. outage risk)' }, { id: 'C', text: 'Same AZ doesn\'t affect data transfer costs' }, { id: 'D', text: 'Cross-AZ transfers are always free for microservices' }], correct: ['B'], explanation: 'Trade-off: same AZ = free transfers + no AZ fault tolerance vs. multi-AZ = $0.01/GB each direction + resilient to AZ failure. For most production workloads, AZ resilience is worth the $0.01/GB inter-AZ cost. For dev/test or cost-sensitive internal services, same-AZ deployment is acceptable.', distractors: { A: 'True that same AZ is free but single AZ is a reliability risk.', C: 'Same AZ transfers between instances are free — inter-AZ is $0.01/GB.', D: 'Cross-AZ transfers are $0.01/GB each way — not free.' } },
  { id: 'd4-net-010', domain: 4, topics: ['CloudFront', 'price class', 'cost optimization'], type: 'single', stem: 'A CloudFront distribution serves content globally but 90% of users are in North America and Europe. Asia-Pacific and South America edge locations cost more per GB. What reduces CloudFront costs without significantly affecting most users?', options: [{ id: 'A', text: 'Serve all users from the origin (S3) directly' }, { id: 'B', text: 'CloudFront Price Class 100' }, { id: 'C', text: 'Disable CloudFront for all regions except US' }, { id: 'D', text: 'Use separate CloudFront distributions per region' }], correct: ['B'], explanation: 'CloudFront Price Classes: All (all edges), 200 (most regions), 100 (North America and Europe only — cheapest). Price Class 100 has the lowest per-GB rate. Users outside included regions are served from the nearest included edge — slightly higher latency but significantly lower cost.', distractors: { A: 'Bypassing CloudFront increases S3 egress costs and latency.', C: 'CloudFront doesn\'t have per-region on/off — Price Classes are the correct mechanism.', D: 'Multiple distributions don\'t reduce per-GB rates.' } },
  { id: 'd4-net-011', domain: 4, topics: ['Global Accelerator', 'cost', 'vs CloudFront'], type: 'single', stem: 'A company uses AWS Global Accelerator ($0.025/hour per accelerator + $0.015/GB) for a non-HTTP application. For HTTP/HTTPS applications, CloudFront could serve the same purpose. What is the cost consideration?', options: [{ id: 'A', text: 'Global Accelerator is always cheaper than CloudFront' }, { id: 'B', text: 'CloudFront is typically cheaper for HTTP/HTTPS with caching; Global Accelerator is better for TCP/UDP applications and non-HTTP protocols; choose based on protocol needs' }, { id: 'C', text: 'They have identical pricing' }, { id: 'D', text: 'Use both simultaneously for best performance' }], correct: ['B'], explanation: 'Global Accelerator: $0.025/hour accelerator + $0.015/GB data transfer. CloudFront: $0.00/hour + $0.01-0.085/GB (lower for cached content). For HTTP applications, CloudFront\'s caching reduces origin requests and is generally cheaper. Global Accelerator excels for non-HTTP (gaming, IoT, VoIP) and when caching isn\'t applicable.', distractors: { A: 'CloudFront is cheaper for cacheable HTTP content — Global Accelerator has a flat hourly charge.', C: 'Pricing structures are different — they\'re not identically priced.', D: 'Using both for the same traffic would double-charge data transfer.' } },
  { id: 'd4-net-012', domain: 4, topics: ['VPN', 'cost'], type: 'single', stem: 'A Site-to-Site VPN costs $0.05/hour per VPN connection (regardless of traffic). Two tunnels per connection are available. What reduces VPN hourly costs?', options: [{ id: 'A', text: 'Add more VPN connections for redundancy' }, { id: 'B', text: 'Consolidate multiple VPN connections using Transit Gateway' }, { id: 'C', text: 'VPN hourly costs cannot be reduced' }, { id: 'D', text: 'Switch to hardware VPN appliances' }], correct: ['B'], explanation: 'Multiple Site-to-Site VPN connections at $0.05/hour each can be consolidated. Transit Gateway with a single attachment (or fewer attachments using ECMP) reduces VPN connection count. However, TGW attachment itself costs $0.05/hour per attachment — evaluate net benefit based on your topology.', distractors: { A: 'Adding connections increases hourly charges.', C: 'VPN consolidation via TGW can reduce connection count and costs.', D: 'Hardware VPN appliances are on-premises devices — don\'t change AWS VPN hourly pricing.' } },
  { id: 'd4-net-013', domain: 4, topics: ['S3', 'data transfer', 'free tier'], type: 'single', stem: 'Data transferred from S3 to EC2 in the same AWS region. What is the cost?', options: [{ id: 'A', text: '$0.09/GB' }, { id: 'B', text: 'Free' }, { id: 'C', text: '$0.01/GB' }, { id: 'D', text: '$0.0007/1,000 requests' }], correct: ['B'], explanation: 'S3-to-EC2 data transfer within the same AWS region is free. This is a key cost optimization: store data in S3 in the same region as your compute (EC2, Lambda, ECS). Cross-region S3-to-EC2 incurs data transfer charges.', distractors: { A: 'Internet egress rates apply when data leaves AWS to the internet — same-region AWS-to-AWS is free.', C: '$0.01/GB is inter-AZ rate — S3-to-EC2 same region is free.', D: 'Request pricing is separate from data transfer pricing.' } },
  { id: 'd4-net-014', domain: 4, topics: ['data transfer', 'inbound'], type: 'single', stem: 'A company uploads 100 TB of data from on-premises to S3 over the internet. What is the inbound data transfer cost to AWS?', options: [{ id: 'A', text: '$0.09/GB × 100 TB ≈ $9,216' }, { id: 'B', text: 'Free' }, { id: 'C', text: '$0.02/GB' }, { id: 'D', text: '$0.05/GB' }], correct: ['B'], explanation: 'Inbound data transfer to AWS from the internet is free for all services (S3, EC2, etc.). Only OUTBOUND (egress) data transfer from AWS to the internet is charged. This asymmetry encourages moving data into AWS — you don\'t pay for ingestion.', distractors: { A: '$0.09/GB is the outbound internet egress rate — not inbound.', C: '$0.02/GB is cross-region — inbound from internet is free.', D: 'No inbound data transfer charge to AWS.' } },
  { id: 'd4-net-015', domain: 4, topics: ['PrivateLink', 'cost', 'vs public endpoint'], type: 'single', stem: 'Traffic from a VPC to S3 can go through a Gateway VPC Endpoint (free) or through NAT Gateway (paid). What is the cost difference?', options: [{ id: 'A', text: 'S3 Gateway Endpoint and NAT Gateway cost the same' }, { id: 'B', text: 'S3 Gateway VPC Endpoint is free (no data processing charge); NAT Gateway charges $0.045/GB processed; at high volume, the savings are significant' }, { id: 'C', text: 'Gateway Endpoint is more expensive than NAT Gateway' }, { id: 'D', text: 'Both routes incur internet egress charges' }], correct: ['B'], explanation: 'S3 and DynamoDB Gateway Endpoints are free to create and have no data processing charges. Routing S3 traffic through NAT Gateway at $0.045/GB is wasteful — the endpoint routes traffic directly within the AWS backbone. Always add S3 Gateway Endpoints to private subnet VPCs.', distractors: { A: 'Gateway Endpoint is free; NAT Gateway has per-GB data processing charges.', C: 'Gateway Endpoints are free — never more expensive.', D: 'Neither route incurs internet egress — both stay within the AWS network.' } },
  { id: 'd4-net-016', domain: 4, topics: ['Transit Gateway', 'peering', 'cost'], type: 'single', stem: 'Two Transit Gateways in different regions need to route traffic between them. TGW peering costs $0.02/GB (peering data transfer). TGW attachment data processing costs $0.02/GB. What is the total per-GB cost for cross-region TGW traffic?', options: [{ id: 'A', text: '$0.02/GB (just peering)' }, { id: 'B', text: '$0.02/GB TGW peering + standard inter-region data transfer (~$0.02/GB) = ~$0.04/GB; plus TGW data processing at each end' }, { id: 'C', text: 'Cross-region TGW is free' }, { id: 'D', text: '$0.09/GB (internet rate)' }], correct: ['B'], explanation: 'Cross-region TGW peering costs include: (1) TGW peering attachment data transfer (~$0.02/GB), plus (2) inter-region data transfer for the underlying traffic. Total approximately $0.04-0.07/GB depending on regions. For high-volume inter-region traffic, consider whether Direct Connect or CloudFront provides a better cost model.', distractors: { A: 'Peering data transfer is one component — inter-region transfer adds additional cost.', C: 'Cross-region TGW is definitely not free.', D: '$0.09/GB internet rate doesn\'t apply to AWS backbone inter-region transfers.' } },
  { id: 'd4-net-017', domain: 4, topics: ['data transfer', 'cost modeling', 'architecture'], type: 'single', stem: 'An architecture has EC2 in us-east-1 pulling 10 TB daily from S3 in eu-west-1. Monthly cost: $0.02/GB × 10 TB × 30 days ≈ $6,144. What architectural change eliminates this cost?', options: [{ id: 'A', text: 'Use Direct Connect for cheaper cross-region' }, { id: 'B', text: 'Move the S3 bucket to the same region as EC2 (us-east-1)' }, { id: 'C', text: 'Use S3 Transfer Acceleration' }, { id: 'D', text: 'Compress data before transfer' }], correct: ['B'], explanation: 'The simplest cost optimization is data locality: place S3 buckets in the same region as the compute that consumes them. S3-to-EC2 in the same region is free. Moving the bucket eliminates $6,144/month. Use S3 CRR if the bucket must also be in eu-west-1 for European users.', distractors: { A: 'Direct Connect is cheaper per GB ($0.02) but doesn\'t reduce the transfer to zero.', C: 'Transfer Acceleration accelerates uploads — doesn\'t reduce download costs from cross-region access.', D: 'Compression reduces bytes transferred — doesn\'t eliminate cross-region charges; same region is free regardless of size.' } },
  { id: 'd4-net-018', domain: 4, topics: ['ALB', 'NLB', 'cost comparison'], type: 'single', stem: 'A load balancer must handle 1 billion TCP connections per month with small payloads. ALB charges per LCU (Load Balancer Capacity Unit); NLB charges per NLCU. For high-connection TCP workloads, which is typically more cost-effective?', options: [{ id: 'A', text: 'ALB' }, { id: 'B', text: 'NLB' }, { id: 'C', text: 'They cost the same at high volume' }, { id: 'D', text: 'Gateway Load Balancer for all TCP workloads' }], correct: ['B'], explanation: 'NLB is generally more cost-effective for high-volume TCP connections with small payloads. ALB LCU pricing includes HTTP rule evaluations which aren\'t relevant for TCP passthrough. NLB NLCU pricing for connections is lower. For HTTP/HTTPS with ALB features (routing rules, authentication), ALB is necessary despite potentially higher cost.', distractors: { A: 'ALB\'s HTTP-aware features add to its cost model — not beneficial for pure TCP.', C: 'NLB is designed for TCP at scale with more favorable per-connection pricing.', D: 'GWLB is for inline appliance insertion — not general-purpose load balancing.' } },
  { id: 'd4-net-019', domain: 4, topics: ['Direct Connect', 'hosted connection', 'cost'], type: 'single', stem: 'A company needs 200 Mbps of Direct Connect connectivity. A dedicated DX port starts at 1 Gbps ($1,620/month). What lower-cost option provides 200 Mbps connectivity?', options: [{ id: 'A', text: 'Site-to-Site VPN (cheaper but over internet)' }, { id: 'B', text: 'Direct Connect Hosted Connection from a partner' }, { id: 'C', text: 'Direct Connect cannot provide less than 1 Gbps' }, { id: 'D', text: 'Use multiple VPN connections aggregated (ECMP)' }], correct: ['B'], explanation: 'Direct Connect Partners offer Hosted Connections (dedicated to a customer within a partner\'s physical port) at 50 Mbps, 100 Mbps, 200 Mbps, 300 Mbps, 400 Mbps, and 500 Mbps. Lower port costs than dedicated connections. One virtual interface per hosted connection.', distractors: { A: 'VPN provides internet connectivity — lacks Direct Connect\'s consistent latency and private path guarantees.', C: 'Hosted Connections via partners provide sub-Gbps connectivity.', D: 'VPN ECMP over TGW provides bandwidth aggregation but still over internet — not equivalent to Direct Connect.' } },
  { id: 'd4-net-020', domain: 4, topics: ['data transfer', 'same-region', 'services'], type: 'single', stem: 'Lambda in us-east-1 invokes an API Gateway endpoint in us-east-1, which calls RDS in us-east-1. What data transfer charges apply?', options: [{ id: 'A', text: '$0.09/GB for each service-to-service call' }, { id: 'B', text: 'Generally free for same-region AWS service-to-service data transfer; exceptions exist (e.g., inter-AZ transfers are $0.01/GB)' }, { id: 'C', text: '$0.01/GB for all managed service traffic' }, { id: 'D', text: 'API Gateway charges data transfer; Lambda and RDS are free' }], correct: ['B'], explanation: 'Same-region data transfer between AWS managed services is generally free. Exceptions: inter-AZ transfers are $0.01/GB. If Lambda, API Gateway, and RDS are all in us-east-1 (same region), the service-to-service data transfer is $0. Design regional architectures to keep services co-located.', distractors: { A: '$0.09/GB internet egress rates don\'t apply to intra-AWS service calls.', C: '$0.01/GB applies to inter-AZ EC2 transfers — not same-region managed service calls.', D: 'API Gateway data transfer applies to the internet-facing endpoint, not internal service calls.' } },
  { id: 'd4-net-021', domain: 4, topics: ['VPC', 'peering', 'inter-AZ'], type: 'single', stem: 'Two VPCs are peered within the same region. Traffic between EC2 instances in the same AZ (across VPCs) via peering — what data transfer cost applies?', options: [{ id: 'A', text: '$0.01/GB each way (same as intra-VPC inter-AZ)' }, { id: 'B', text: 'Free for same-AZ peering transfers using private IPs' }, { id: 'C', text: '$0.05/GB for peering data processing' }, { id: 'D', text: '$0.09/GB same as internet' }], correct: ['A'], explanation: 'VPC peering data transfer pricing: same-AZ = free (per AWS documentation, same-AZ private IP traffic across peered VPCs is free). Inter-AZ across peered VPCs = $0.01/GB each way. Cross-region peered VPCs = standard inter-region rates (~$0.02/GB).', distractors: { B: 'AWS documentation confirms same-AZ peering using private IPs is free — A is the more nuanced correct answer.', C: 'VPC peering has no separate data processing charge — only data transfer charges.', D: 'Peering uses the AWS backbone — not internet rates.' } },
  { id: 'd4-net-022', domain: 4, topics: ['Egress Only', 'IPv6', 'cost'], type: 'single', stem: 'EC2 instances with IPv6 addresses use an Egress-Only Internet Gateway for outbound internet access. What is the cost of the Egress-Only Internet Gateway?', options: [{ id: 'A', text: '$0.045/hour (same as NAT Gateway)' }, { id: 'B', text: 'Free' }, { id: 'C', text: '$0.01/hour' }, { id: 'D', text: '$0.045/GB processed (same as NAT Gateway)' }], correct: ['B'], explanation: 'Egress-Only Internet Gateways (EOIGW) for IPv6 outbound traffic are free (no hourly charge, no data processing charge). Standard internet egress data transfer rates apply for data exiting to the internet. This is a cost advantage of IPv6 over IPv4 (NAT Gateway adds $0.045/hour + $0.045/GB processing).', distractors: { A: 'NAT Gateway charges hourly ($0.045) — EOIGW has no hourly charge.', C: 'There is no EOIGW hourly charge — it is completely free.', D: 'NAT Gateway charges data processing — EOIGW has no data processing charge.' } },
  { id: 'd4-net-023', domain: 4, topics: ['Direct Connect', 'data transfer cost', 'vs internet'], type: 'single', stem: 'Direct Connect public VIF carries traffic from on-premises to AWS S3. Data transfer from AWS to on-premises over Direct Connect is $0.02/GB. Over the internet, S3 internet egress is $0.09/GB. At what monthly volume does Direct Connect break even on data transfer costs?', options: [{ id: 'A', text: 'Direct Connect always saves on data transfer' }, { id: 'B', text: 'Break-even depends on DX port cost: $0.07/GB savings × monthly volume must exceed port cost; at ~$1,620/month port, need ~23 TB/month for data transfer savings to cover port cost' }, { id: 'C', text: 'Direct Connect is more expensive than internet for data transfer' }, { id: 'D', text: 'Direct Connect data transfer is free' }], correct: ['B'], explanation: 'DX data transfer savings: $0.09 - $0.02 = $0.07/GB saved. To recover $1,620/month port cost: $1,620 / $0.07 = 23,142 GB ≈ 23 TB/month break-even. Below 23 TB/month, internet is cheaper for pure data transfer; above it, DX saves money (plus provides consistent latency).', distractors: { A: 'Small volumes don\'t recover the fixed port cost — DX is only cost-effective at sufficient scale.', C: 'DX data transfer per GB is cheaper ($0.02) than internet egress ($0.09) — but fixed port cost affects break-even.', D: 'DX data transfer is cheaper than internet but not free.' } },
  { id: 'd4-net-024', domain: 4, topics: ['Internet Gateway', 'cost'], type: 'single', stem: 'An Internet Gateway (IGW) is used for EC2 instances to access the internet. What does the IGW itself cost?', options: [{ id: 'A', text: '$0.045/hour per Internet Gateway' }, { id: 'B', text: 'Internet Gateways are free' }, { id: 'C', text: '$0.01/GB for all traffic through IGW' }, { id: 'D', text: '$0.05/hour like NAT Gateway' }], correct: ['B'], explanation: 'Internet Gateways have no hourly charge — free to create and run. The associated data transfer costs (EC2-to-internet egress) are charged at standard internet egress rates. This differs from NAT Gateway ($0.045/hour + $0.045/GB data processing) and Virtual Private Gateways (also free but data transfer charges apply).', distractors: { A: 'NAT Gateways have hourly charges — Internet Gateways do not.', C: 'IGW itself has no data processing charge — only the standard EC2 internet egress rates.', D: '$0.05/hour NAT Gateway rate does not apply to Internet Gateways.' } },
  { id: 'd4-net-025', domain: 4, topics: ['Elastic IP', 'cost'], type: 'single', stem: 'A company has 100 Elastic IP addresses allocated but only 30 are in use (attached to running instances). What are the cost implications for the 70 unused EIPs?', options: [{ id: 'A', text: 'Elastic IPs are always free' }, { id: 'B', text: 'Unused Elastic IPs (not attached to running instances) are charged $0.005/hour each' }, { id: 'C', text: 'Only used EIPs are charged' }, { id: 'D', text: '$0.05/hour for unused EIPs' }], correct: ['B'], explanation: 'Elastic IPs: free when attached to a running instance. Charged at $0.005/hour when not associated with a running instance (or associated with a stopped instance). Release unused EIPs to avoid unnecessary charges. Use Trusted Advisor to find idle EIPs.', distractors: { A: 'EIPs are free only when in use (attached to running instance) — idle EIPs are charged.', C: 'Unused/idle EIPs are explicitly charged to encourage releasing addresses when not needed.', D: '$0.005/hour is the correct rate — not $0.05/hour.' } },
  { id: 'd4-net-026', domain: 4, topics: ['CloudFront', 'WAF', 'cost addition'], type: 'single', stem: 'Adding AWS WAF to a CloudFront distribution protects against web attacks. What costs does WAF add?', options: [{ id: 'A', text: 'WAF is free when used with CloudFront' }, { id: 'B', text: 'WAF charges: $5/month per WebACL + $1/month per rule + $0.60/million web requests; significant for high-traffic distributions' }, { id: 'C', text: 'WAF adds $0.01/GB to CloudFront pricing' }, { id: 'D', text: 'WAF is included with AWS Shield Standard' }], correct: ['B'], explanation: 'AWS WAF pricing: $5/WebACL/month + $1/rule/month + $0.60/million requests. For a distribution receiving 100 million requests/month with 10 WAF rules: $5 + $10 + $60 = $75/month WAF cost on top of CloudFront charges. Managed Rule Groups add $1-2/rule group/month.', distractors: { A: 'WAF has explicit pricing — not included free with CloudFront.', C: 'WAF is per-request pricing, not per-GB.', D: 'Shield Standard provides basic DDoS protection — WAF rules for application filtering are separately priced.' } },
  { id: 'd4-net-027', domain: 4, topics: ['data transfer', 'S3 Cross-Region', 'optimization'], type: 'single', stem: 'An application in us-west-2 frequently reads the same 100 MB dataset from S3 in us-east-1. Cross-region transfer cost: $0.02/GB × 100 MB = $0.002 per read. 10,000 reads/day = $20/day. What eliminates this cost?', options: [{ id: 'A', text: 'Use S3 Transfer Acceleration' }, { id: 'B', text: 'Copy the dataset to an S3 bucket in us-west-2' }, { id: 'C', text: 'Cache at the application layer' }, { id: 'D', text: 'Use S3 Gateway Endpoint in us-west-2' }], correct: ['B'], explanation: 'Data locality is the most direct cost optimization. Copy the static dataset to us-west-2. Same-region S3 reads are free. One-time cross-region copy cost ($0.002) is immediately recouped. If data updates, use S3 SRR (Same-Region Replication) from us-east-1 to us-west-2 bucket.', distractors: { A: 'Transfer Acceleration is for faster uploads — doesn\'t reduce download cost from cross-region.', C: 'Application caching reduces repeat reads — effective if reads are to the same data, but data still needs to be fetched once per server.', D: 'S3 Gateway Endpoints are for same-region access — don\'t help with cross-region transfers.' } },
  { id: 'd4-net-028', domain: 4, topics: ['Transit Gateway', 'cost', 'attachment hours'], type: 'single', stem: 'A Transit Gateway has 10 VPC attachments and 2 VPN attachments at $0.05/attachment/hour. Monthly attachment cost is 12 × $0.05 × 730 = $438. Data processing is $0.02/GB. How can attachment costs be reduced?', options: [{ id: 'A', text: 'Disconnect rarely used VPCs temporarily' }, { id: 'B', text: 'Evaluate if infrequently-communicating VPCs can use VPC peering instead of TGW' }, { id: 'C', text: 'Use a single TGW for multiple regions' }, { id: 'D', text: 'TGW attachment costs cannot be reduced' }], correct: ['B'], explanation: 'VPC peering has no hourly attachment fee — only data transfer costs. For VPCs that rarely communicate, peering may be cheaper than TGW attachment ($36.50/month/attachment). Evaluate: if monthly data transfer < 1,825 GB (at $0.02/GB TGW processing), peering costs less. Keep TGW for complex routing; use peering for simple point-to-point.', distractors: { A: 'Disconnecting VPCs disrupts connectivity — not practical for production environments.', C: 'A single TGW covers one region — doesn\'t reduce attachment count or cost.', D: 'Replacing TGW with peering for simple VPC pairs eliminates attachment fees.' } },
  { id: 'd4-net-029', domain: 4, topics: ['Lambda', 'data transfer', 'in VPC'], type: 'single', stem: 'Lambda functions in a VPC call each other via ALB. Each call transfers 1 KB. At 10 million invocations/day, what data transfer charges apply?', options: [{ id: 'A', text: '$0.09/GB for all Lambda data transfer' }, { id: 'B', text: 'Lambda data transfer within the same region and same AZ is free; inter-AZ transfers are $0.01/GB; network traffic to/from Lambda is charged at standard rates' }, { id: 'C', text: 'Lambda functions have no data transfer charges' }, { id: 'D', text: '$0.005/GB for Lambda-to-Lambda calls' }], correct: ['B'], explanation: 'Lambda data transfer follows the same rules as EC2: same AZ = free, inter-AZ = $0.01/GB, internet egress = $0.09/GB. At 10 million × 1 KB = 10 GB/day, if all in the same AZ through an internal ALB, data transfer is free. If inter-AZ, $0.01/GB × 10 GB = $0.10/day.', distractors: { A: 'Internet egress rates only apply when Lambda sends data to the internet — not for internal AWS traffic.', C: 'Lambda follows standard EC2-equivalent data transfer pricing.', D: 'No special Lambda-to-Lambda rate — standard transfer pricing applies.' } },
  { id: 'd4-net-030', domain: 4, topics: ['VPN', 'accelerated', 'cost'], type: 'single', stem: 'Standard Site-to-Site VPN uses the internet for the majority of the path. Accelerated VPN uses Global Accelerator to improve performance. What additional cost does Accelerated VPN add?', options: [{ id: 'A', text: 'No additional cost' }, { id: 'B', text: 'Accelerated VPN adds Global Accelerator charges: $0.025/hour per accelerator + $0.015/GB data transfer surcharge on top of standard VPN connection charges' }, { id: 'C', text: 'Accelerated VPN replaces standard charges' }, { id: 'D', text: '$0.10/hour surcharge for acceleration' }], correct: ['B'], explanation: 'Accelerated VPN creates a Global Accelerator endpoint for the VPN. Adds: $0.025/hour per accelerator + $0.015/GB data transfer on top of VPN charges. For international offices where internet latency is a problem, the performance benefit may justify the additional cost.', distractors: { A: 'Accelerated VPN uses Global Accelerator infrastructure — Global Accelerator adds explicit charges.', C: 'Accelerated VPN adds cost; it doesn\'t replace standard charges.', D: '$0.025/hour is the Global Accelerator hourly rate — not $0.10.' } },
  { id: 'd4-net-031', domain: 4, topics: ['NAT Gateway', 'S3 bypass', 'architecture'], type: 'single', stem: 'A monthly bill analysis shows EC2 instances in private subnets spend $500/month in NAT Gateway data processing charges, 80% of which is S3 traffic. What single change reduces this bill most?', options: [{ id: 'A', text: 'Add more NAT Gateways for redundancy' }, { id: 'B', text: 'Add an S3 VPC Gateway Endpoint' }, { id: 'C', text: 'Switch to Public NAT Instance' }, { id: 'D', text: 'Upgrade to a larger NAT Gateway' }], correct: ['B'], explanation: 'S3 Gateway VPC Endpoint is free and routes S3 traffic directly within the VPC without going through NAT Gateway. For $500/month with 80% S3: saving $400/month from S3 traffic alone. Add the endpoint to the private subnet route tables — immediate and free.', distractors: { A: 'More NAT Gateways increase HA but also increase per-AZ hourly cost.', C: 'NAT Instance is cheaper per hour but adds management overhead; doesn\'t save as much as a free S3 endpoint.', D: 'NAT Gateway doesn\'t have "sizes" to upgrade — it scales automatically.' } },
  { id: 'd4-net-032', domain: 4, topics: ['CloudFront', 'real-time logs', 'cost'], type: 'single', stem: 'CloudFront real-time logs send every request to Kinesis Data Streams. At 100 million requests/day, the log volume is high. Standard logs to S3 are free. What is the cost implication of real-time logs?', options: [{ id: 'A', text: 'Real-time logs to Kinesis are free' }, { id: 'B', text: 'Real-time logs incur charges: CloudFront charges $0.01/million log lines + Kinesis Data Streams shard costs; standard S3 access logs are free but near real-time' }, { id: 'C', text: 'Standard and real-time logs cost the same' }, { id: 'D', text: 'Real-time logs are free but Kinesis charges apply' }], correct: ['B'], explanation: 'CloudFront real-time logs: CloudFront charges $0.01/million log records + Kinesis Data Streams shard charges. At 100 million/day: $1/day in CloudFront log charges + Kinesis costs. Standard CloudFront access logs to S3 are free but have 15-60 minute delivery delay. Use real-time only when near-real-time log analysis is essential.', distractors: { A: 'CloudFront charges per million log records for real-time logs — not free.', C: 'Standard S3 logs are free; real-time logs have explicit charges.', D: 'CloudFront also charges per log record — not just Kinesis.' } },
  { id: 'd4-net-033', domain: 4, topics: ['data transfer', 'availability zones', 'multi-AZ cost'], type: 'multi', stem: 'A multi-AZ architecture has data transfer costs between AZs. Which TWO actions reduce inter-AZ data transfer costs without compromising availability?', options: [{ id: 'A', text: 'Consolidate all services into a single AZ' }, { id: 'B', text: 'Place cache (ElastiCache) in each AZ to serve local requests' }, { id: 'C', text: 'Use ALB path-based routing to direct requests to same-AZ targets when possible' }, { id: 'D', text: 'Disable Multi-AZ on RDS' }], correct: ['B', 'C'], explanation: 'Per-AZ caching (B) reduces cross-AZ reads by serving cache hits locally. ALB cross-zone load balancing distributes evenly (may increase AZ transfers) — use target groups with AZ affinity routing (C) to reduce unnecessary cross-AZ hops. Both maintain multi-AZ availability.', distractors: { A: 'Single AZ eliminates transfers but loses fault tolerance — the opposite of the goal.', D: 'Disabling RDS Multi-AZ eliminates standby costs but sacrifices HA — not appropriate.' } },
  { id: 'd4-net-034', domain: 4, topics: ['Interface Endpoints', 'private DNS', 'cost'], type: 'single', stem: 'A company creates Interface Endpoints for 15 AWS services across 3 AZs. Each endpoint costs $0.01/hour × 3 AZs. Monthly cost: 15 × 3 × $0.01 × 730 = $328.50 just in endpoint hours. Is this justified?', options: [{ id: 'A', text: 'Interface Endpoints are always cost-justified regardless of traffic volume' }, { id: 'B', text: 'Compare endpoint cost ($328.50/month) vs NAT Gateway processing cost for those services; only create endpoints where the traffic volume makes them economical; prioritize high-volume services (S3/STS/EC2/SSM)' }, { id: 'C', text: 'Use NAT Gateway for all services to avoid endpoint complexity' }, { id: 'D', text: 'Interface Endpoints should not span multiple AZs' }], correct: ['B'], explanation: 'Each Interface Endpoint: $0.01/hour × 3 AZs ≈ $21.90/month + $0.01/GB. Compare to NAT processing: $0.045/GB. Break-even: endpoint hour cost recovered when NAT processing savings exceed endpoint cost. At 486 GB/month per endpoint ($21.90 / $0.035/GB saved), it becomes economical. Only deploy endpoints for high-traffic services.', distractors: { A: 'Low-traffic service endpoints may cost more in hourly fees than they save in NAT processing.', C: 'For high-volume AWS API calls, Interface Endpoints save more than NAT processing costs.', D: 'Multi-AZ endpoints provide HA — appropriate for production.' } },
  { id: 'd4-net-035', domain: 4, topics: ['data transfer', 'AZ', 'ELB'], type: 'single', stem: 'An ALB has cross-zone load balancing enabled (default). It distributes traffic from AZ-1 to targets in AZ-2. Does ALB cross-zone load balancing incur data transfer charges?', options: [{ id: 'A', text: 'Yes' }, { id: 'B', text: 'For ALB: cross-zone load balancing is free (no inter-AZ data transfer charges for ALB); NLB and GWLB cross-zone transfers are charged' }, { id: 'C', text: 'Cross-zone load balancing has no data transfer implications' }, { id: 'D', text: 'All load balancer cross-zone traffic is charged at $0.01/GB' }], correct: ['B'], explanation: 'ALB cross-zone load balancing is enabled by default and does NOT incur inter-AZ data transfer charges. NLB and GWLB cross-zone load balancing is disabled by default and DOES incur $0.01/GB inter-AZ charges when enabled. This is an important distinction for cost modeling.', distractors: { A: 'ALB specifically exempts cross-zone traffic from data transfer charges — NLB/GWLB do not.', C: 'There is a cost difference between ALB (free) and NLB/GWLB (charged) cross-zone traffic.', D: 'ALB cross-zone is free; NLB/GWLB cross-zone is $0.01/GB — B is the correct nuance.' } },
  { id: 'd4-net-036', domain: 4, topics: ['cost modeling', 'network', 'architecture review'], type: 'single', stem: 'A solution architect is reviewing a proposal where Lambda functions make frequent API calls to DynamoDB through a NAT Gateway. The NAT data processing charges are high. What architectural fix eliminates these charges?', options: [{ id: 'A', text: 'Move Lambda to a public subnet' }, { id: 'B', text: 'Add a DynamoDB VPC Gateway Endpoint' }, { id: 'C', text: 'Use DynamoDB Accelerator (DAX) to reduce calls' }, { id: 'D', text: 'Move Lambda out of the VPC' }], correct: ['B'], explanation: 'DynamoDB Gateway VPC Endpoints are free and bypass NAT Gateway. Lambda in a private VPC subnet should always route DynamoDB and S3 traffic through Gateway Endpoints — not NAT Gateway. This is a common architectural oversight with significant cost impact at scale.', distractors: { A: 'Lambda in public subnets requires internet access configuration — not the clean solution.', C: 'DAX reduces DynamoDB call volume — doesn\'t eliminate NAT Gateway charges for the calls that do occur.', D: 'Lambda outside VPC loses private resource connectivity — not appropriate if VPC resources are needed.' } },
  { id: 'd4-net-037', domain: 4, topics: ['outposts', 'data transfer'], type: 'single', stem: 'An application runs on AWS Outposts (on-premises). Traffic between Outposts and the parent AWS region goes over the Local Gateway or service link. What data transfer cost applies for Outposts-to-region traffic?', options: [{ id: 'A', text: 'Outposts-to-region traffic is free' }, { id: 'B', text: 'Data transfer from Outposts to the parent AWS region over the service link is charged at standard data transfer rates; inbound to Outposts is free' }, { id: 'C', text: 'Outposts traffic uses internet pricing ($0.09/GB)' }, { id: 'D', text: 'All Outposts traffic is charged at Direct Connect rates' }], correct: ['B'], explanation: 'Outposts data transfer: outbound from Outposts to the parent region is charged at standard rates. Inbound to Outposts is free. The service link (private connection to AWS region over AWS backbone) carries control plane and data plane traffic. Plan data locality to minimize outbound region data transfer.', distractors: { A: 'Outposts-to-region outbound is charged — only inbound is free.', C: 'Outposts uses service link (private, not internet) — not public internet egress rates.', D: 'Outposts service link is not Direct Connect — uses separate pricing.' } },
  { id: 'd4-net-038', domain: 4, topics: ['CloudFront', 'HTTP/3', 'free'], type: 'single', stem: 'A company enables HTTP/3 (QUIC) on their CloudFront distribution for improved mobile performance. What additional cost does HTTP/3 on CloudFront incur?', options: [{ id: 'A', text: '$0.01/GB surcharge for HTTP/3 traffic' }, { id: 'B', text: 'No additional charge' }, { id: 'C', text: '$50/month per distribution for HTTP/3' }, { id: 'D', text: 'HTTP/3 requires a premium CloudFront plan' }], correct: ['B'], explanation: 'HTTP/3 (QUIC) on CloudFront is enabled at no additional charge beyond standard CloudFront pricing. Same data transfer rates apply. Enablement is opt-in at the distribution level. No CloudFront "plans" exist — all features are included.', distractors: { A: 'HTTP/3 adds no per-GB surcharge.', C: 'No per-distribution charges for enabling HTTP/3.', D: 'CloudFront doesn\'t have premium tiers — pricing is purely usage-based.' } },
  { id: 'd4-net-039', domain: 4, topics: ['data transfer', 'free tier', 'first 100 GB'], type: 'single', stem: 'A new AWS account\'s first month has 95 GB of EC2 internet egress. What is the egress charge?', options: [{ id: 'A', text: '$0.09 × 95 GB = $8.55' }, { id: 'B', text: 'Free' }, { id: 'C', text: '$0.01 × 95 GB = $0.95' }, { id: 'D', text: 'Free only for the first 12 months' }], correct: ['B'], explanation: 'The first 100 GB/month of internet egress from EC2 (and several other services) is always free — not just for new accounts. This applies to the aggregate across all services in the account. The 101st GB starts at $0.09/GB. This free tier applies permanently, not just the first 12 months.', distractors: { A: '$0.09/GB applies after the 100 GB free tier — the first 100 GB is free.', C: '$0.01/GB is inter-AZ transfer pricing — not internet egress.', D: 'The 100 GB/month free tier is permanent — not limited to 12 months.' } },
  { id: 'd4-net-040', domain: 4, topics: ['data transfer', 'cost architecture'], type: 'single', stem: 'A data analytics pipeline: EC2 reads from S3 (same region = free), transforms data, writes results to S3 (same region = free), then sends 500 GB to an on-premises analytics server. What is the primary data transfer cost?', options: [{ id: 'A', text: 'S3-to-EC2 same region data transfer' }, { id: 'B', text: '500 GB outbound to on-premises (~$0.09/GB × 500 GB = $45/month)' }, { id: 'C', text: 'EC2-to-S3 write charges' }, { id: 'D', text: 'All transfers in this pipeline are free' }], correct: ['B'], explanation: 'Same-region S3-to-EC2 and EC2-to-S3 are free. The 500 GB to on-premises is outbound internet egress at ~$0.09/GB = ~$45/month. This is the only meaningful data transfer cost in this pipeline. Consider Direct Connect if this pattern occurs at higher volumes.', distractors: { A: 'S3-to-EC2 same-region is free.', C: 'EC2-to-S3 same-region is free.', D: 'The 500 GB to on-premises is not free — internet egress applies.' } },
  { id: 'd4-net-041', domain: 4, topics: ['Route 53', 'cost'], type: 'single', stem: 'A Route 53 hosted zone with 10 records receives 1 billion DNS queries per month. What are the Route 53 cost components?', options: [{ id: 'A', text: 'Free' }, { id: 'B', text: '$0.50/month per hosted zone + $0.40/million queries for first 1 billion = $400.50/month for queries + health checks if configured' }, { id: 'C', text: '$0.01/million queries (very cheap)' }, { id: 'D', text: '$10/month flat regardless of queries' }], correct: ['B'], explanation: 'Route 53 pricing: $0.50/hosted zone/month + $0.40/million queries for first 1 billion, $0.20/million after. 1 billion queries = $400/month in query charges + $0.50/month hosted zone. Health check charges are separate ($0.50-$3/check/month). For high-traffic zones, Route 53 query costs are significant.', distractors: { A: 'Route 53 has explicit query and hosted zone charges.', C: '$0.01/million is not the Route 53 query rate — it\'s $0.40/million.', D: 'Route 53 is metered per query — not a flat monthly fee.' } },
  { id: 'd4-net-042', domain: 4, topics: ['VPN', 'split tunneling', 'cost'], type: 'single', stem: 'Client VPN users route ALL traffic through the VPN, including internet browsing. This maximizes VPN data transfer charges. What configuration reduces VPN traffic volume?', options: [{ id: 'A', text: 'Increase VPN bandwidth' }, { id: 'B', text: 'Enable split tunneling on Client VPN' }, { id: 'C', text: 'Use smaller VPN client package' }, { id: 'D', text: 'Use SSL VPN instead of IPsec' }], correct: ['B'], explanation: 'Client VPN charges $0.10/hour per active connection + $0.05/GB data processed. Split tunneling sends only corporate traffic through the VPN — internet traffic bypasses. Reduces VPN data processing charges by routing non-corporate traffic directly. Common optimization for remote workforce VPN costs.', distractors: { A: 'VPN bandwidth changes instance type — doesn\'t reduce data volume.', C: 'VPN client size is software — doesn\'t affect data transfer charges.', D: 'AWS Client VPN uses TLS — IPsec/SSL distinction doesn\'t apply here.' } },
  { id: 'd4-net-043', domain: 4, topics: ['data transfer', 'CloudFront', 'origin fetch'], type: 'single', stem: 'A CloudFront distribution serves 1 TB/day from cache (cache hit ratio 95%). The origin (ALB+EC2) only serves 50 GB/day. Without CloudFront, the origin would need to serve 1 TB/day. What cost savings does CloudFront provide?', options: [{ id: 'A', text: 'CloudFront increases total cost' }, { id: 'B', text: 'CloudFront saves the difference between EC2 internet egress on 950 GB/day ($85.50/day) vs CloudFront delivery ($0.009-0.085/GB); plus reduces origin infrastructure requirements' }, { id: 'C', text: 'Both approaches cost exactly the same' }, { id: 'D', text: 'CloudFront only saves bandwidth' }], correct: ['B'], explanation: 'CloudFront offloads 95% of requests from the origin. Infrastructure savings: fewer/smaller EC2 instances needed, fewer ALB requests. Bandwidth savings: CloudFront-to-user pricing < EC2 direct egress. Cache hit ratio directly correlates to cost savings — high cache ratio = less origin egress = lower total cost.', distractors: { A: 'CloudFront reduces origin load and egress costs — typically cheaper than serving all users from EC2 directly.', C: 'The cost structures are different — CloudFront is typically cheaper for popular cached content.', D: 'Infrastructure savings from smaller origin requirements are also significant.' } },
  { id: 'd4-net-044', domain: 4, topics: ['cost allocation', 'network', 'tagging'], type: 'single', stem: 'A company wants to understand data transfer costs per application team. What enables data transfer cost allocation in AWS Cost Explorer?', options: [{ id: 'A', text: 'Data transfer costs are automatically tagged by service' }, { id: 'B', text: 'Apply cost allocation tags to VPCs, NAT Gateways, load balancers, and other network resources; activate tags in Billing; filter Cost Explorer by tag' }, { id: 'C', text: 'Data transfer costs cannot be attributed to specific teams' }, { id: 'D', text: 'Use AWS Config for data transfer tracking' }], correct: ['B'], explanation: 'Apply cost allocation tags (e.g., Team=payments, Environment=prod) to network resources: NAT Gateways, ELBs, VPC endpoints, Transit Gateway attachments. Activate in Billing console. Cost Explorer can then group/filter data transfer costs by tag. Note: some data transfer costs are shown at the EC2 level, not separately.', distractors: { A: 'AWS doesn\'t auto-tag by application/team — tags must be applied manually or via automation.', C: 'Cost allocation tags enable team-level data transfer attribution.', D: 'AWS Config tracks resource changes — not billing cost allocation.' } },
  { id: 'd4-net-045', domain: 4, topics: ['data transfer', 'total cost', 'exam pattern'], type: 'single', stem: 'A solution architect calculates monthly data transfer costs for a 3-tier web app: ALB internet-facing (1 TB ingress: free, 2 TB egress: $180), EC2 to RDS (same AZ: free), EC2 to ElastiCache (same AZ: free), EC2 to S3 (same region: free). Which data transfer component actually incurs cost?', options: [{ id: 'A', text: 'EC2 to RDS inter-AZ traffic' }, { id: 'B', text: 'Internet egress from the load balancer/EC2 to end users' }, { id: 'C', text: 'S3 to EC2 data reads' }, { id: 'D', text: 'ALB to EC2 target group traffic' }], correct: ['B'], explanation: 'In a well-architected single-region, same-AZ deployment: inbound is free, same-region AWS-to-AWS is free, same-AZ is free. The ONLY significant data transfer cost is outbound to the internet (end users). Design choices that reduce egress (caching, CloudFront, compression) directly reduce the monthly bill.', distractors: { A: 'EC2 to RDS in same AZ is free — inter-AZ RDS traffic would be $0.01/GB but same AZ is zero.', C: 'S3 to EC2 same region is free.', D: 'ALB to targets within the same AZ are free; inter-AZ ALB traffic is free for ALB (cross-zone load balancing is free for ALB).' } },
]
